const parts = $('Message a model').first().json.content.parts;

 // Find the part that is NOT a thought (the actual response)
 const responsePart = parts.find(p => !p.thought);
 const rawText = responsePart.text.replace(/```json|```/g, "").trim();

 let result;
 try {
   result = JSON.parse(rawText);
 } catch (e) {
   result = {
     lik_codes: ["unknown"],
     location_context: "unknown"
   };
 }

 const chatId = $('check-message-and-user').first().json.payload.from;

 const beachMap = ({
   "120363406629965480@g.us": "pantai_lampuuk",
   "120363425830719164@g.us": "pantai_lhoknga"
 });

 return {
   lik_codes: result.lik_codes || ["unknown"],
   location_context: result.location_context || "unknown",
   beach_location: beachMap[chatId] || "unknown_beach"
 };

